// Exhaustive keyword scan: probe candidate words in batches, report those that get uppercased.
import { execFile } from 'node:child_process';
import { appendFileSync, writeFileSync } from 'node:fs';
const EXE = '/workspace/dataset/test4_executable';
const OUT = process.argv[2];
const MINLEN = Number(process.argv[3]), MAXLEN = Number(process.argv[4]);
const BATCH = 800, CONC = 40;
writeFileSync(OUT, '');

// generator over all lowercase words of length MINLEN..MAXLEN
function* words() {
  const A = 'abcdefghijklmnopqrstuvwxyz';
  for (let L = MINLEN; L <= MAXLEN; L++) {
    const idx = new Array(L).fill(0);
    for (;;) {
      let s = '';
      for (let k = 0; k < L; k++) s += A[idx[k]];
      yield s;
      let p = L - 1;
      while (p >= 0 && ++idx[p] === 26) { idx[p] = 0; p--; }
      if (p < 0) break;
    }
  }
}
const gen = words();
let done = false, batches = 0, found = 0;
function nextBatch() {
  if (done) return null;
  const b = [];
  for (let k = 0; k < BATCH; k++) { const n = gen.next(); if (n.done) { done = true; break; } b.push(n.value); }
  return b.length ? b : null;
}
function work(cb) {
  const b = nextBatch();
  if (!b) return cb();
  execFile(EXE, ['--a', b.join(' , ')], { maxBuffer: 1 << 26, encoding: 'utf8' }, (err, so) => {
    if (err) { console.error('ERR batch', b[0], err.message); process.exit(1); }
    const parts = so.replace(/\n$/, '').split(' , ');
    if (parts.length !== b.length) { console.error('MISALIGN at', b[0], parts.length, b.length); process.exit(1); }
    const hits = [];
    for (let k = 0; k < b.length; k++) if (parts[k] !== b[k]) hits.push(b[k] + '\t' + parts[k]);
    if (hits.length) { appendFileSync(OUT, hits.join('\n') + '\n'); found += hits.length; }
    if (++batches % 500 === 0) console.error(`batches=${batches} found=${found} last=${b[b.length-1]}`);
    work(cb);
  });
}
let fin = 0;
const cb = () => { if (++fin === CONC) console.error(`DONE batches=${batches} found=${found}`); };
for (let i = 0; i < CONC; i++) work(cb);
EOF
