import { execFile } from 'node:child_process';
import { readFileSync, appendFileSync, writeFileSync } from 'node:fs';
const EXE = '/workspace/dataset/test4_executable';
const [,, listFile, outFile, batchS, concS] = process.argv;
const BATCH = Number(batchS||800), CONC = Number(concS||40);
let cands = readFileSync(listFile,'utf8').split('\n').map(s=>s.trim()).filter(Boolean);
cands = [...new Set(cands)];
writeFileSync(outFile,'');
let i = 0, found = 0, batches = 0, bad = 0;
function work(cb){
  if (i >= cands.length) return cb();
  const b = cands.slice(i, i+BATCH); i += BATCH;
  execFile(EXE, ['--a', b.join(',')], {maxBuffer:1<<28, encoding:'utf8'}, (err, so) => {
    if (err) { console.error('EXEC ERR', b[0]); return work(cb); }
    const parts = so.replace(/\n$/,'').split(',');
    if (parts.length !== b.length) { bad++; }
    else { const hits=[]; for(let k=0;k<b.length;k++) if(parts[k]!==b[k]) hits.push(b[k]+'\t'+parts[k]);
           if(hits.length){appendFileSync(outFile,hits.join('\n')+'\n');found+=hits.length;} }
    if(++batches%300===0) console.error(`batches=${batches} found=${found} misaligned=${bad}`);
    work(cb);
  });
}
let fin=0; const cb=()=>{ if(++fin===CONC) console.error(`DONE cands=${cands.length} batches=${batches} found=${found} misalignedBatches=${bad}`); };
for(let k=0;k<CONC;k++) work(cb);
EOF
